 /** 原页读取同次固定运行的持久事件；节点原帧保真，结束只取中心实际终态。 */
 private JSONObject javaLegacyPage(JSONObject task){
  var receipt=javaDebugBuild.getJSONObject("debugReceipt");
  assertEquals(task.get("workflowVersionId"),Long.toString(receipt.getLongValue("workflowVersionId")));
  assertEquals(task.get("dslHash"),receipt.get("dslHash"));
  assertEquals(task.getString("runId"),javaDebugAttachment.runId());
  assertEquals(receipt.getLongValue("workflowVersionId"),javaDebugAttachment.workflowVersionId());
  assertEquals(space,javaDebugAttachment.spaceId());
  var page=javaDebugBridge.page(javaDebugAttachment,0);
  assertTrue(page.terminal());assertFalse(page.waiting());assertEquals("COMPLETED",page.state());
  assertEquals(runs.find(task.getString("runId")).getLastEventSeq(),page.watermark());assertEquals(page.watermark(),page.scannedThrough());
  assertEquals(7,page.frames().size(),"原三节点各开始/完成原帧，另一个真正中心终态");
  var frames=new JSONArray();var started=new HashSet<String>();var completed=new HashSet<String>();int terminals=0;
  var storedFrames=new LinkedHashMap<String,JSONObject>();var run=runs.find(task.getString("runId"));
  for(var row:runs.eventsThrough(run.getId(),0,run.getLastEventSeq(),1000)){
   var event=ModelMessageSources.sourceObject(row.eventJson());var raw=event.getJSONObject("payload").getJSONObject("legacyFrame");
   if(raw!=null){var expected=ToolOpenApi.copy(raw);if("python".equals(task.get("engineProfile")))assertEquals(task.get("runId"),raw.get("id"));else expected.put("id",task.get("runId"));storedFrames.put(task.getString("runId")+":"+row.seq(),expected);}
  }
  assertEquals(6,storedFrames.size());
  for(var value:page.frames()){
   assertTrue(value.id().startsWith(task.getString("runId")+":"));var frame=value.data();var node=frame.getJSONObject("workflow_step").getJSONObject("node");String nodeId=node.getString("id");
   if("flow_obj".equals(nodeId)){terminals++;assertEquals("stop",frame.getJSONArray("choices").getJSONObject(0).get("finish_reason"));}
   else{assertTrue(ToolSchema.same(storedFrames.remove(value.id()),frame),"原帧message/code/extra/null与节点输入输出须完整保留");assertNull(frame.getJSONArray("choices").getJSONObject(0).get("finish_reason"));if(node.get("finish_reason")==null)assertTrue(started.add(nodeId));else{assertEquals("stop",node.get("finish_reason"));assertTrue(completed.add(nodeId));}}
   frames.add(JSONObject.of("eventId",value.id(),"frame",frame));
  }
  var expectedNodes=new HashSet<String>();for(Object raw:task.getJSONObject("dsl").getJSONArray("nodes"))expectedNodes.add(((JSONObject)raw).getString("id"));
  assertEquals(expectedNodes,started);assertEquals(started,completed);assertEquals(1,terminals);
  assertTrue(storedFrames.isEmpty());
  assertEquals("flow_obj",page.frames().getLast().data().getJSONObject("workflow_step").getJSONObject("node").get("id"));
  long nodeCursor=com.ruoyi.paiflow.adapter.legacy.LegacyDebugBridgeService.cursor(page.frames().get(2).id(),task.getString("runId"),page.watermark());
  var resumed=javaDebugBridge.page(javaDebugAttachment,nodeCursor);assertEquals(page.frames().subList(3,page.frames().size()),resumed.frames());assertTrue(resumed.terminal());
  var drained=javaDebugBridge.page(javaDebugAttachment,page.scannedThrough());assertTrue(drained.frames().isEmpty());assertTrue(drained.terminal());assertEquals(1,sends.get(),"回读/续读不得重做工具调用");
  return JSONObject.of("debugBuild",javaDebugBuild,"runId",task.get("runId"),"workflowVersionId",task.get("workflowVersionId"),"spaceId",javaDebugAttachment.spaceId(),"scannedThrough",page.scannedThrough(),"watermark",page.watermark(),"terminal",page.terminal(),"state",page.state(),"frames",frames,"resumedFrom",nodeCursor,"resumedFrameCount",resumed.frames().size(),"drainedFrameCount",drained.frames().size());
 }

 /** 同一个真实H2运行中实时调用现有中心服务；子进程只隔离Java21原引擎依赖，不开网络服务。 */
 private JSONObject javaWorkerBridge(JSONObject task,JSONObject expectedRequest)throws Exception{
  return workerBridge(task,expectedRequest,"paiflow.worker.pipeCommandFile");
 }
 private JSONObject workerBridge(JSONObject task,JSONObject expectedRequest,String commandProperty)throws Exception{
  var command=JSON.parseArray(Files.readString(Path.of(System.getProperty(commandProperty)))).toJavaList(String.class);String directory=System.getProperty("paiflow.center.javaToolCaptureDir");assertNotNull(directory,"实时闭环必须保存实际请求与回执");var root=Path.of(directory);Files.createDirectories(root);var workerOutput=root.resolve("worker-"+task.getString("runId")+".json");command=new ArrayList<>(command);command.add(Instant.now().toString());command.add(workerOutput.toAbsolutePath().toString());var process=new ProcessBuilder(command).redirectError(root.resolve("worker-"+task.getString("runId")+".stderr.log").toFile()).start();var reader=java.util.concurrent.Executors.newSingleThreadExecutor();var transcript=new JSONArray();var events=new JSONArray();JSONObject operationAck=null,finalResult=null;int claims=0,begins=0,operationsStarted=0;
  try(var input=new java.io.BufferedReader(new java.io.InputStreamReader(process.getInputStream(),java.nio.charset.StandardCharsets.UTF_8));var output=new java.io.BufferedWriter(new java.io.OutputStreamWriter(process.getOutputStream(),java.nio.charset.StandardCharsets.UTF_8))){
   for(int count=0;count<128;count++){
    var pending=reader.submit(()->input.readLine());String line;try{line=pending.get(15,java.util.concurrent.TimeUnit.SECONDS);}catch(Exception failure){process.destroyForcibly();pending.cancel(true);throw failure;}if(line==null)break;var message=JSON.parseObject(line);if("result".equals(message.get("type"))){finalResult=message.getJSONObject("result");break;}var trace=JSONObject.of("request",message);transcript.add(trace);assertEquals("request",message.get("type"));assertEquals("POST",message.get("method"));String path=message.getString("path");var body=message.getJSONObject("body");JSONObject value=null;int status=200;JSONObject envelope;
    try{
     if(path.equals("/internal/paiflow/v1/runs/claim")){assertEquals(0,claims++);if("python".equals(worker.engineProfile()))assertTrue(ToolSchema.same(JSONObject.of("engineProfile","python"),body));else assertTrue(body.isEmpty());value=task;}
     else{String prefix="/internal/paiflow/v1/runs/"+task.getString("runId")+"/";assertTrue(path.startsWith(prefix),"实际Worker跨Run路径");String action=path.substring(prefix.length());switch(action){
      case "lease/verify"-> {value=leases.verify(task.getString("runId"),worker,body.getString("leaseId"),RunLeaseService.attempt(body));javaVerify=value;}
      case "execution/begin"-> {assertEquals(0,begins++);value=leases.beginExecution(task.getString("runId"),worker,body.getString("leaseId"),RunLeaseService.attempt(body));javaBegin=value;}
      case "heartbeat"->value=leases.heartbeat(task.getString("runId"),worker,body.getString("leaseId"),RunLeaseService.attempt(body));
      case "events"-> {value=leases.append(task.getString("runId"),worker,body);events.add(ToolOpenApi.copy(body));}
      case "operations"-> {assertEquals(0,operationsStarted++);assertTrue(ToolSchema.same(expectedRequest,body),"原Worker自然键与完整请求须等于原算法及当前固定资源");value=operations.start(task.getString("runId"),worker,body);operationAck=value;}
      case "result"->value=leases.result(task.getString("runId"),worker,body);
      default->{if(action.startsWith("resources/"))value=operations.resource(task.getString("runId"),worker,java.net.URLDecoder.decode(action.substring("resources/".length()),java.nio.charset.StandardCharsets.UTF_8),body);else throw new AssertionError("未实现的实际Worker入口 "+action);}
     }}envelope=JSONObject.of("code",200,"msg","操作成功","data",value);
    }catch(ServiceException failure){status=failure.getCode();envelope=JSONObject.of("code",failure.getCode(),"msg",failure.getMessage());}
    var reply=JSONObject.of("id",message.get("id"),"status",status,"body",envelope);trace.put("response",reply);output.write(JSON.toJSONString(reply,JSONWriter.Feature.WriteMapNullValue));output.newLine();output.flush();
   }
   assertTrue(process.waitFor(15,java.util.concurrent.TimeUnit.SECONDS),"原Worker未退出");assertEquals(0,process.exitValue(),"原Worker失败，保留stderr和transcript");assertNotNull(finalResult);assertEquals("COMPLETED",finalResult.get("state"));assertEquals("COMPLETED",runs.find(task.getString("runId")).getState());assertEquals(1,claims);assertEquals(1,begins);assertEquals(1,operationsStarted);assertNotNull(operationAck);assertTrue(Files.exists(workerOutput));var actual=JSON.parseObject(Files.readString(workerOutput));assertTrue(ToolSchema.same(finalResult,actual.get("result")));return JSONObject.of("operationAck",operationAck,"events",events,"result",finalResult,"transcript",transcript,"workerOutput",actual);
  }finally{reader.shutdownNow();if(process.isAlive())process.destroyForcibly();Files.writeString(root.resolve("transcript-"+task.getString("runId")+".json"),JSON.toJSONString(transcript,JSONWriter.Feature.PrettyFormat,JSONWriter.Feature.WriteMapNullValue));}
 }
