   assertNotNull(javaHttpCapture);assertEquals("POST",javaHttpCapture.get("method"));assertEquals("/%E5%8E%9F%E9%80%8F%E4%BC%A0?question=%E5%8E%9F%E6%9F%A5%E8%AF%A2",javaHttpCapture.get("uri"));assertEquals("{\"defaulted\": \"\\u4fdd\\u7559\\u9ed8\\u8ba4\"}",javaHttpCapture.get("body"));String legacyText=ack.getJSONObject("legacyResponse").getJSONObject("payload").getJSONObject("text").getString("text");assertTrue(ToolSchema.same(JSON.parseObject(responseText),JSON.parseObject(legacyText)));assertEquals("{\"answer\": \"原HTTP输出\", \"count\": 0}",legacyText);
   var expected=JSONObject.of("answer","原HTTP输出","count",0);var run=runs.find(task.getString("runId"));var accepted=new JSONArray();for(var event:runs.eventsThrough(run.getId(),0,run.getLastEventSeq(),1000))accepted.add(ModelMessageSources.sourceObject(event.eventJson()));var events=bridge.getJSONArray("events");assertEquals(6,events.size(),"Python原三节点各开始及完成，不套Java事件数量");assertEquals(7,accepted.size());for(int i=0;i<events.size();i++)assertTrue(ToolSchema.same(events.get(i),accepted.get(i)));
   var end=DataWorkerOperationService.find(task.getJSONObject("dsl"),"node-end::e");var values=new CompletedOutputSources(tools,session.getMapper(ModelOperationMapper.class),mock(CheckpointMapper.class)).values(run,task.getJSONObject("dsl"),end,accepted);assertTrue(ToolSchema.same(expected,values));assertTrue(ToolSchema.same(expected,ToolCompletedSources.completed(run,DataWorkerOperationService.find(task.getJSONObject("dsl"),"plugin::cap"),tools)));var actualResult=bridge.getJSONArray("transcript").stream().map(raw->(JSONObject)raw).filter(trace->trace.getJSONObject("request").getString("path").endsWith("/result")).findFirst().orElseThrow().getJSONObject("request").getJSONObject("body");var expectedOutput=JSONObject.of("outputs",expected,"content","","reasoningContent","","usage",JSONObject.of("completion_tokens",0,"prompt_tokens",0,"total_tokens",0));assertTrue(ToolSchema.same(expectedOutput,actualResult.get("output")));assertTrue(ToolSchema.same(actualResult,ModelMessageSources.sourceObject(run.getResultJson())));
   var page=javaLegacyPage(task);var capture=JSONObject.of("scope","原页默认Python固定调试版本/同次Run、原Factory/TaskRunner实时stdio、正式Service/Mapper/ManagedProducer及临时回环端点；无项目服务/真实业务库/供应商/浏览器验收","referenceApi",refs,"assignment",task,"verify",firstVerify,"lastVerify",javaVerify,"begin",javaBegin,"actualOperationRequest",expectedRequest,"actualOperationAck",ack,"acceptedEvents",accepted,"verifiedEndInputs",values,"actualResultRequest",actualResult,"persistedResult",ModelMessageSources.sourceObject(run.getResultJson()),"actualWorker",bridge,"actualToolHttp",javaHttpCapture,"actualLegacyPage",page);
