 /** 临时回环端点只提供确定技术响应；实际请求必须经过正式Producer、原Worker和同次中心账本。 */
 private void javaManagedHttpPipeline(String name)throws Exception{
  var gold=javaGold(name);JSONObject receipt=null;
  for(Object raw:gold.getJSONArray("actualResponses")){var data=((JSONObject)raw).getJSONObject("data");if(data!=null&&data.get("legacyResponse") instanceof JSONObject response)receipt=response;}
  assertNotNull(receipt);String responseText=receipt.getJSONObject("payload").getJSONObject("text").getString("text");
  var local=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);
  local.createContext("/",exchange->{
   sends.incrementAndGet();var headers=new JSONObject();exchange.getRequestHeaders().forEach((key,value)->headers.put(key.toLowerCase(Locale.ROOT),new JSONArray(value)));
   javaHttpCapture=JSONObject.of("method",exchange.getRequestMethod(),"uri",exchange.getRequestURI().toString(),"headers",headers,"body",new String(exchange.getRequestBody().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8),"responseStatus",200,"responseBody",responseText);
   byte[] response=responseText.getBytes(java.nio.charset.StandardCharsets.UTF_8);exchange.sendResponseHeaders(200,response.length);exchange.getResponseBody().write(response);exchange.close();
  });
  var managed=new ManagedToolProducer(catalog,new ModelPrivateTransport(),Clock.systemUTC());
  try{
   actualHttp=true;testEndpoint="http://127.0.0.1:"+local.getAddress().getPort();javaManagedProducer=managed;local.start();
   javaPipeline(gold);
   assertNotNull(javaHttpCapture);assertEquals("POST",javaHttpCapture.get("method"));
   assertEquals("/%E5%8E%9F%E9%80%8F%E4%BC%A0%E8%B7%AF%E5%BE%84?q=%E5%8E%9F%E6%9F%A5%E8%AF%A2%E9%BB%98%E8%AE%A4",javaHttpCapture.get("uri"));
   // JDK技术端点按ISO-8859-1映射头部字节；逐字节核UTF8原值，不改写捕获或正式出口。
   var hbiz=javaHttpCapture.getJSONObject("headers").getJSONArray("hbiz");assertEquals(1,hbiz.size());
   assertArrayEquals("BFS第一项".getBytes(java.nio.charset.StandardCharsets.UTF_8),hbiz.getString(0).getBytes(java.nio.charset.StandardCharsets.ISO_8859_1));
   assertFalse(javaHttpCapture.getJSONObject("headers").containsKey("h"));
   assertEquals("{\"flag\": false, \"count\": 0, \"optional\": \"\\u7a7a\\u8f93\\u5165\\u9ed8\\u8ba4\", \"nested\": {\"leaf\": \"\\u5b9e\\u9645\\u5d4c\\u5957\"}}",javaHttpCapture.get("body"));
   assertEquals(1,sends.get());
  }finally{javaManagedProducer=null;managed.close();local.stop(0);}
 }
